from escritura_base import unidad as U, iglesia as I, pregunta as P, modulo

SE4 = modulo("se-4", "Sagrada Escritura IV: Exégesis A.T. I: Pentateuco", "Génesis, Éxodo, Levítico, Números y Deuteronomio",
 "Estudio del Pentateuco: su estructura y formación, los relatos de los orígenes, los patriarcas, el éxodo y la alianza, y la Ley como camino de vida. 5 unidades de 90 minutos, un taller de cierre y una evaluación.",
 "El Pentateuco es la Torá, el corazón de la Biblia de Israel. Allí están la creación, las promesas a los patriarcas, la liberación de Egipto, la alianza del Sinaí y la Ley. En este módulo vas a leerlo con herramientas de estudio y con fe.",
 "Cada participante prepara una catequesis de 15 minutos sobre un relato del Pentateuco para la edad que acompaña (por ejemplo, la creación, Abraham, José, la zarza ardiente o el maná). Debe explicar el género del texto, su mensaje teológico y su relación con Jesús, evitando lecturas literalistas. Se presentan en grupos pequeños con retroalimentación.",
 [
  U("El Pentateuco: estructura y formación",
    "Conocer los cinco libros del Pentateuco, su hilo conductor y las principales explicaciones sobre su formación.",
    "Los cinco primeros libros de la Biblia forman una unidad: cuentan la historia desde la creación del mundo hasta la muerte de Moisés a las puertas de la tierra prometida. Los judíos la llaman Torá, que significa enseñanza o instrucción.",
    [("Cinco libros, una historia", "- **Génesis:** orígenes del mundo y de la humanidad (1–11) y patriarcas (12–50).\n- **Éxodo:** esclavitud en Egipto, liberación, alianza en el Sinaí.\n- **Levítico:** leyes sobre el culto y la santidad.\n- **Números:** marcha por el desierto.\n- **Deuteronomio:** discursos de despedida de Moisés en Moab.\n\nEl hilo conductor es la **promesa** de Dios: una descendencia, una tierra y una bendición para todos los pueblos."),
     ("¿Lo escribió Moisés?", "La tradición judía y cristiana atribuyó el Pentateuco a Moisés, por su papel central. Pero el propio texto narra su muerte (Deuteronomio 34) y muestra repeticiones, estilos distintos y relatos duplicados (por ejemplo, dos relatos de la creación). Por eso los estudiosos piensan que es fruto de un largo proceso."),
     ("Hipótesis sobre su formación", "Durante mucho tiempo se habló de cuatro fuentes o documentos (la llamada hipótesis documentaria). Hoy muchos estudiosos prefieren hablar de **tradiciones y bloques** que se fueron reuniendo y que recibieron su forma final en torno al **exilio y el posexilio**. Es un debate abierto entre especialistas."),
     ("Lo que importa para la fe", "La Iglesia no impone una teoría sobre la composición. Lo que afirma es que el Pentateuco es Palabra de Dios inspirada y que Moisés está en el origen de la tradición de la Ley. Conocer su formación ayuda a entender por qué hay distintas voces y a leer cada texto en su contexto.")],
    ("Génesis 12,1-3 · La promesa a Abraham", "Dios llama a Abraham y le promete hacer de él un gran pueblo, darle una tierra y que en él sean bendecidas todas las familias de la tierra. Esta triple promesa recorre todo el Pentateuco y, para los cristianos, se cumple en Cristo, por quien la bendición llega a todos los pueblos."),
    [I("Dei Verbum 14", "Dios, buscando y preparando la salvación de todo el género humano, eligió un pueblo al que confiar sus promesas; hizo alianza con Abraham y, por medio de Moisés, con el pueblo de Israel."),
     I("Verbum Domini 34", "La interpretación de la Escritura requiere el uso de los métodos históricos, unido a la lectura en la fe de la Iglesia.")],
    ["¿Qué libros del Pentateuco has leído?", "¿Te sorprende que no haya sido escrito por una sola persona?", "¿Cómo explicarías los dos relatos de la creación?", "¿Qué significa para ti la promesa de bendición a todos los pueblos?"],
    "Comparen Génesis 1,1–2,4a y Génesis 2,4b-25. Hagan una tabla con el orden de la creación, el nombre de Dios, el estilo y el mensaje central de cada relato.",
    "Dios de Abraham, que prometiste bendecir a todos los pueblos: gracias por tu fidelidad a lo largo de la historia. Que al estudiar tu Ley descubra tu enseñanza para la vida. Amén.",
    "Escribe qué recuerdas de cada uno de los cinco libros del Pentateuco.",
    ["Describir la estructura y el hilo del Pentateuco.", "Conocer las explicaciones sobre su formación.", "Distinguir lo que es debate académico de lo que es fe."],
    ("Nombres de Dios", "En el Pentateuco Dios aparece con distintos nombres: Elohim (Dios) y el nombre propio revelado a Moisés, YHWH, que los judíos no pronuncian y leen como Adonai (el Señor). Las traducciones católicas suelen escribir «el Señor»."),
    ("Los dos relatos", "Un catequizando nota que en Génesis 1 el ser humano es creado al final y en Génesis 2, antes que los animales. Pregunta cuál es el verdadero.", ["¿Cómo responderías?", "¿Qué enseña cada relato?"]),
    [["Torá", "Instrucción o enseñanza; nombre judío del Pentateuco."], ["Promesa", "Descendencia, tierra y bendición prometidas a Abraham."], ["YHWH", "Nombre propio de Dios revelado a Moisés."]],
    ["En ti serán bendecidas todas las familias. ¿Para quién eres bendición?", "Agradece por las promesas de Dios en tu vida.", "Lee Génesis 12–15 esta semana."],
    ["Lean los dos relatos.", "Hagan la tabla.", "Comparen mensajes.", "Compartan."],
    "El Pentateuco es la historia de una promesa."),
  U("Génesis 1–11: los orígenes",
    "Comprender el género y el mensaje de los relatos de los orígenes: creación, pecado, diluvio y Babel.",
    "Los once primeros capítulos del Génesis no son un informe científico ni una crónica, sino relatos que responden a las grandes preguntas: ¿de dónde venimos?, ¿por qué existe el mal?, ¿qué lugar tenemos en el mundo?",
    [("El género de estos relatos", "Son relatos con lenguaje simbólico, que dialogan con mitos de otros pueblos del antiguo Oriente (por ejemplo, de Mesopotamia) pero los transforman profundamente. La Iglesia enseña que expresan verdades fundamentales en un lenguaje adaptado a la mentalidad de la época."),
     ("La creación", "- Dios crea todo con su palabra; la creación es **buena**.\n- El ser humano es **imagen de Dios**, varón y mujer, con dignidad única.\n- El sábado muestra que la creación culmina en el descanso y la relación con Dios.\n- Frente a los mitos que divinizaban el sol o la luna, Génesis los presenta como simples lámparas creadas."),
     ("El pecado y sus consecuencias", "Génesis 3 narra la ruptura de la confianza con Dios: el ser humano quiere ser como Dios sin Dios. Las consecuencias se extienden: vergüenza, culpa, ruptura con el otro, con la creación. Caín y Abel, el diluvio y Babel muestran cómo el mal crece. La Iglesia ve aquí el **pecado original**."),
     ("La fidelidad de Dios", "Junto al pecado, aparece siempre la gracia: Dios viste a Adán y Eva, protege a Caín, salva a Noé y hace alianza con toda la creación (el arco iris). Después de Babel, Dios llama a Abraham: comienza la historia de la salvación.")],
    ("Génesis 1,26-31 · A imagen de Dios", "Dios crea al ser humano a su imagen, varón y mujer, lo bendice y le confía la creación. Al final ve que todo es «muy bueno». Este texto funda la dignidad de toda persona y la responsabilidad de cuidar el mundo."),
    [I("Catecismo de la Iglesia Católica 337 y 390", "Dios mismo presenta la obra de la creación en un lenguaje simbólico; el relato de la caída utiliza un lenguaje de imágenes, pero afirma un acontecimiento primordial."),
     I("Dei Verbum 12", "Para entender lo que el autor quiso afirmar hay que atender a los modos de pensar, de expresarse y de narrar de su tiempo.")],
    ["¿Cómo explicarías que estos relatos son verdaderos sin ser crónicas?", "¿Qué te dice que el ser humano sea imagen de Dios?", "¿Dónde ves hoy la lógica de Babel?", "¿Cómo presentarías el pecado original a jóvenes?"],
    "En grupos, cada uno toma un relato (creación, caída, Caín y Abel, diluvio, Babel) y responde: ¿qué pregunta humana responde?, ¿qué dice de Dios?, ¿qué dice del ser humano?, ¿dónde aparece la gracia?",
    "Dios creador, que viste que todo era muy bueno: gracias por mi vida y por la de cada persona, hecha a tu imagen. Cuando el pecado rompe la armonía, recuérdame que tu gracia es más fuerte. Amén.",
    "Escribe tres preguntas grandes que te haces sobre el origen del mundo o del mal.",
    ["Reconocer el género de los relatos de los orígenes.", "Explicar su mensaje teológico.", "Relacionar pecado y gracia en Génesis 1–11."],
    ("Evolución y creación", "La Iglesia no se opone a la teoría de la evolución como explicación científica del desarrollo de la vida, siempre que no se pretenda negar la acción creadora de Dios ni la dignidad espiritual del ser humano."),
    ("La manzana", "Un niño pregunta en la catequesis por qué Dios castigó a Adán por comerse una manzana.", ["¿Qué hay que aclarar del texto?", "¿Cómo explicarías el sentido del relato?"]),
    [["Imagen de Dios", "Dignidad propia del ser humano."], ["Pecado original", "Ruptura primera con Dios que afecta a toda la humanidad."], ["Alianza con Noé", "Alianza de Dios con toda la creación."]],
    ["Vio Dios que era muy bueno. ¿Qué bien de la creación has olvidado mirar?", "Reza el Salmo 8.", "Cuida esta semana algo de la creación."],
    ["Elijan un relato.", "Respondan las cuatro preguntas.", "Comparen.", "Presenten."],
    "Antes que el pecado está la bondad de la creación, y después del pecado, la gracia."),
  U("Génesis 12–50: los patriarcas",
    "Conocer los ciclos de Abraham, Isaac, Jacob y José, y su mensaje sobre la fe, la promesa y la reconciliación.",
    "Con Abraham comienza la historia de un pueblo. Los relatos de los patriarcas son historias familiares llenas de fe, dudas, conflictos y reconciliaciones. En ellas Dios camina con personas imperfectas.",
    [("Abraham, padre de los creyentes", "Abraham deja su tierra confiando en una promesa. Su fe es puesta a prueba: la espera del hijo, la tentación de buscar atajos (Agar), y el sacrificio de Isaac (Génesis 22), donde Dios no quiere la muerte del hijo y provee. Pablo lo presenta como modelo de la fe que justifica."),
     ("Isaac y Jacob", "**Isaac** es el hijo de la promesa. **Jacob**, su hijo, es astuto y engaña a su hermano Esaú para quedarse con la bendición. Aun así, Dios lo elige: en Betel sueña con una escalera al cielo y en el río Yaboc lucha con Dios y recibe un nombre nuevo: **Israel**."),
     ("José y sus hermanos", "José, el hijo preferido, es vendido por sus hermanos y llega a Egipto, donde se convierte en gobernador. Cuando sus hermanos llegan por el hambre, José los pone a prueba y finalmente se reconcilia con ellos: «Ustedes quisieron hacerme mal, pero Dios lo convirtió en bien» (Génesis 50,20)."),
     ("Un Dios que camina con familias imperfectas", "Los patriarcas mienten, se pelean, tienen favoritos. La Biblia no los idealiza. Muestra que Dios cumple su promesa a través de personas frágiles y que las heridas familiares pueden sanar.")],
    ("Génesis 15,1-6 · Abraham creyó", "Abraham, ya anciano y sin hijos, se queja ante Dios. Dios lo saca afuera y le dice: «Mira el cielo y cuenta las estrellas: así será tu descendencia». Abraham creyó al Señor, y eso le fue tenido en cuenta como justicia. La fe es confiar en la promesa cuando todavía no se ve."),
    [I("Catecismo de la Iglesia Católica 144-146", "Abraham es el modelo de la obediencia de la fe; por su fe es llamado padre de todos los creyentes."),
     I("Dei Verbum 14", "Dios, al elegir a Abraham, comenzó a preparar un pueblo para sí.")],
    ["¿Qué promesa de Dios te cuesta creer?", "¿Qué te dice que Dios elija a Jacob, que fue tramposo?", "¿Qué heridas familiares necesitan reconciliación?", "¿Cómo presentarías a los patriarcas a niños sin idealizarlos?"],
    "Lean en grupos la historia de José (Génesis 37; 39–45; 50,15-21) y armen una línea de los momentos de caída y de reconciliación. Conversen qué enseña sobre el perdón en la familia y la comunidad.",
    "Dios de Abraham, de Isaac y de Jacob: tú caminas con familias imperfectas y cumples tus promesas. Dame la fe de Abraham para confiar, y el corazón de José para perdonar. Amén.",
    "Piensa en una persona de tu familia con la que necesitas reconciliarte.",
    ["Conocer los ciclos patriarcales.", "Reconocer la fe de Abraham como modelo.", "Relacionar la historia de José con el perdón."],
    ("Las madres de Israel", "Sara, Rebeca, Raquel y Lía también son protagonistas. Varias son estériles y Dios les concede un hijo: la promesa depende de Dios, no de la fuerza humana."),
    ("El favorito", "En una familia de tu grupo, los padres tienen un hijo preferido y los hermanos lo resienten.", ["¿Qué enseña la historia de José?", "¿Cómo acompañarías a esa familia?"]),
    [["Patriarcas", "Abraham, Isaac y Jacob."], ["Israel", "Nombre nuevo de Jacob y de su pueblo."], ["Providencia", "Dios guía la historia, incluso a través del mal."]],
    ["Abraham creyó. ¿En qué te pide Dios confiar?", "Mira el cielo de noche y reza por tus descendientes en la fe.", "Da un paso de reconciliación esta semana."],
    ["Lean la historia de José.", "Armen la línea.", "Conversen sobre el perdón.", "Recen juntos."],
    "Dios cumple sus promesas a través de personas frágiles."),
  U("Éxodo: liberación y alianza",
    "Comprender el mensaje del libro del Éxodo: la liberación de la esclavitud, la Pascua, la alianza del Sinaí y el Decálogo.",
    "El éxodo es la experiencia fundante de Israel: Dios escucha el clamor de un pueblo esclavo, lo libera y hace alianza con él. Para los cristianos, es figura de la Pascua de Jesús y del bautismo.",
    [("Dios que ve y escucha", "En la zarza ardiente (Éxodo 3), Dios se revela a Moisés: «He visto la aflicción de mi pueblo, he oído su clamor, conozco sus sufrimientos y he bajado a liberarlo». Y revela su nombre: **YHWH**, «Yo soy», el Dios presente y fiel."),
     ("La Pascua", "Las plagas muestran el enfrentamiento entre Dios y el faraón. La noche de **Pascua** (Éxodo 12), con el cordero y el pan sin levadura, se convierte en el memorial de la liberación que Israel celebra cada año. Jesús celebró su última cena en el marco de la Pascua."),
     ("El paso del mar y el desierto", "El paso del mar Rojo es el gran signo de la liberación. En el desierto el pueblo murmura, y Dios lo alimenta con el **maná** y le da agua de la roca. Los Padres de la Iglesia vieron aquí figuras del bautismo y de la Eucaristía."),
     ("La alianza del Sinaí", "En el Sinaí, Dios propone una **alianza**: «Ustedes serán mi pueblo y yo seré su Dios». Le da el **Decálogo** (Éxodo 20), las diez palabras, no como una carga, sino como el camino para vivir en libertad. El pueblo pronto rompe la alianza con el becerro de oro, y Dios, por la intercesión de Moisés, perdona.")],
    ("Éxodo 3,1-15 · La zarza ardiente", "Moisés ve una zarza que arde sin consumirse. Dios lo llama, le dice que se quite las sandalias y le revela que ha visto el sufrimiento de su pueblo. Lo envía al faraón y le revela su nombre. Es el texto de la vocación de Moisés y de la revelación del Dios liberador."),
    [I("Catecismo de la Iglesia Católica 204-213 y 2056-2063", "Dios revela su nombre a Moisés y se muestra como el Dios fiel; el Decálogo se comprende en el contexto del éxodo y de la alianza."),
     I("Catecismo de la Iglesia Católica 1221", "El paso del mar Rojo es figura del bautismo, que libera de la esclavitud del pecado.")],
    ["¿Qué esclavitudes viven hoy los jóvenes?", "¿Qué significa que Dios «ve y escucha»?", "¿Cómo presentarías los Diez Mandamientos como camino de libertad?", "¿Dónde se parece tu vida al pueblo que murmura en el desierto?"],
    "Por grupos, relacionen escenas del Éxodo con sacramentos y momentos de la vida de Jesús: Pascua y Última Cena, mar Rojo y bautismo, maná y Eucaristía, Sinaí y sermón de la montaña. Presenten un esquema.",
    "Dios liberador, que ves la aflicción de tu pueblo y escuchas su clamor: libéranos de todo lo que nos esclaviza. Que vivamos tu alianza como camino de libertad y seamos signos de tu liberación para otros. Amén.",
    "Escribe una «esclavitud» de la que te gustaría ser liberado.",
    ["Explicar el sentido del éxodo y la Pascua.", "Comprender la alianza y el Decálogo.", "Relacionar el Éxodo con los sacramentos."],
    ("La historicidad del éxodo", "No hay documentos egipcios que mencionen el éxodo, y su fecha se discute. Muchos estudiosos piensan que el relato conserva la memoria de un grupo que salió de Egipto y que esa experiencia se convirtió en la memoria de todo Israel, narrada con rasgos épicos."),
    ("Los mandamientos como prohibiciones", "Un joven dice que la religión es «puros no». Cita los mandamientos como ejemplo.", ["¿Cómo le presentarías el Decálogo desde Éxodo 20,2?", "¿Qué dijo Jesús sobre la Ley?"]),
    [["Pascua", "Paso; memorial de la liberación de Egipto."], ["Alianza", "Pacto de amor entre Dios y su pueblo."], ["Decálogo", "Las diez palabras del Sinaí."]],
    ["He visto la aflicción de mi pueblo. ¿Qué aflicción ves tú?", "Reza por quienes viven esclavitudes hoy.", "Haz algo concreto por alguien que sufre."],
    ["Relacionen escenas.", "Hagan el esquema.", "Presenten.", "Recen."],
    "Dios ve, escucha y libera."),
  U("Levítico, Números y Deuteronomio",
    "Conocer el mensaje de los tres últimos libros del Pentateuco: la santidad, la marcha por el desierto y la memoria de la alianza.",
    "Estos libros parecen menos atractivos: leyes, censos, discursos. Pero contienen textos fundamentales, como el mandamiento del amor al prójimo y el Shemá Israel, que Jesús citó como el primer mandamiento.",
    [("Levítico: sean santos", "El Levítico regula el culto, los sacrificios y la pureza. Su centro es: «Sean santos, porque yo, el Señor su Dios, soy santo» (19,2). En el mismo capítulo aparece: «**Amarás a tu prójimo como a ti mismo**» (19,18), y también el cuidado del extranjero y del pobre. El **Día de la Expiación** (capítulo 16) prepara la comprensión de la obra de Cristo en Hebreos."),
     ("Números: el desierto", "Números narra la marcha del pueblo por el desierto: censos, quejas, rebeliones, el miedo a entrar en la tierra. Por la falta de confianza, esa generación anda cuarenta años en el desierto. Es un libro sobre la fidelidad de Dios ante la infidelidad del pueblo. Contiene la bendición sacerdotal (6,24-26)."),
     ("Deuteronomio: recuerda", "El Deuteronomio son los discursos de Moisés antes de morir. Repite la Ley y llama a **recordar**: «Acuérdate del camino que el Señor te hizo recorrer». Su corazón es el **Shemá**: «Escucha, Israel: el Señor es nuestro Dios, el Señor es uno. Amarás al Señor tu Dios con todo tu corazón» (6,4-5)."),
     ("La muerte de Moisés", "El Pentateuco termina con Moisés que mira la tierra prometida desde el monte Nebo y muere sin entrar (Deuteronomio 34). La promesa sigue abierta: el pueblo deberá vivirla. Para los cristianos, Jesús es el profeta como Moisés que Dios prometió suscitar (Deuteronomio 18,15).")],
    ("Deuteronomio 6,4-9 · Shemá Israel", "«Escucha, Israel: el Señor es nuestro Dios, el Señor es uno. Amarás al Señor tu Dios con todo tu corazón, con toda tu alma y con todas tus fuerzas». Los judíos lo rezan cada día. Jesús lo cita como el primer mandamiento y lo une al amor al prójimo de Levítico 19,18 (Marcos 12,29-31)."),
    [I("Catecismo de la Iglesia Católica 2083 y 2196", "Jesús resumió los deberes del hombre para con Dios con el Shemá, y unió el amor a Dios y el amor al prójimo."),
     I("Verbum Domini 41", "Jesús se presenta como cumplimiento de la Ley; la unidad de ambos testamentos se ve en el doble mandamiento del amor.")],
    ["¿Sabías que el mandamiento del amor al prójimo está en el Levítico?", "¿Qué desiertos has atravesado y cómo te sostuvo Dios?", "¿Qué necesitas recordar de lo que Dios hizo en tu vida?", "¿Qué te dice que Moisés no entrara a la tierra?"],
    "Memoricen juntos el Shemá (Deuteronomio 6,4-5) y la bendición de Números 6,24-26. Luego, cada uno escribe su propio «Deuteronomio»: un breve discurso a sí mismo recordando lo que Dios ha hecho en su vida.",
    "Escucha, Israel: el Señor es nuestro Dios, el Señor es uno. Señor, quiero amarte con todo mi corazón, con toda mi alma y con todas mis fuerzas, y amar a mi prójimo como a mí mismo. Que el Señor me bendiga y me proteja. Amén.",
    "Escribe tres cosas que Dios hizo en tu vida que no quieres olvidar.",
    ["Reconocer textos clave de Levítico, Números y Deuteronomio.", "Comprender la santidad, el desierto y la memoria como temas teológicos.", "Relacionar el Shemá con el mandamiento de Jesús."],
    ("La bendición de Aarón", "«Que el Señor te bendiga y te proteja; que el Señor haga brillar su rostro sobre ti y te muestre su gracia; que el Señor te descubra su rostro y te conceda la paz» (Números 6,24-26). Se usa en la liturgia del 1 de enero y puede rezarse sobre los jóvenes."),
    ("«Libros aburridos»", "En un grupo de estudio bíblico, varios dicen que el Levítico y los Números son aburridos e inútiles.", ["¿Qué textos de estos libros les mostrarías?", "¿Cómo ayudarles a valorar la Ley?"]),
    [["Santidad", "Pertenencia a Dios que transforma la vida."], ["Shemá", "Oración central de Israel (Deuteronomio 6,4-9)."], ["Memoria", "Recordar las obras de Dios para vivir la alianza."]],
    ["Escucha, Israel. ¿Qué te cuesta escuchar?", "Reza el Shemá al levantarte y al acostarte.", "Bendice a alguien esta semana con Números 6,24-26."],
    ["Memoricen los textos.", "Escriban su discurso.", "Compártanlo.", "Bendíganse."],
    "Escucha, recuerda y ama."),
 ],
 [P("¿Qué significa Torá?", ["Libro", "Instrucción o enseñanza", "Historia"], 1, "Es el nombre judío del Pentateuco."),
  P("¿Cuál es la triple promesa a Abraham?", ["Riqueza, poder y fama", "Descendencia, tierra y bendición", "Templo, rey y ley"], 1, "Génesis 12,1-3."),
  P("¿Cómo se explican hoy las repeticiones del Pentateuco?", ["Por errores de copistas", "Por un largo proceso de formación con varias tradiciones", "Porque Moisés se olvidaba"], 1, "Es un tema de estudio abierto."),
  P("¿Qué enseñan los relatos de Génesis 1–11?", ["Datos científicos sobre el origen del universo", "Verdades fundamentales en lenguaje simbólico", "Leyendas sin valor"], 1, "Catecismo 337 y 390."),
  P("¿Qué nombre recibe Jacob después de luchar con Dios?", ["Israel", "Abraham", "Judá"], 0, "Génesis 32."),
  P("¿Qué revela Dios a Moisés en la zarza ardiente?", ["Su nombre y su decisión de liberar al pueblo", "Las plagas", "El templo"], 0, "Éxodo 3."),
  P("¿Dónde está el mandamiento «amarás a tu prójimo como a ti mismo»?", ["Levítico 19,18", "Génesis 1,27", "Éxodo 3,14"], 0, "Jesús lo une al Shemá."),
  P("¿Qué es el Shemá?", ["Un sacrificio", "La oración «Escucha, Israel» de Deuteronomio 6,4-9", "Una fiesta judía"], 1, "Jesús lo cita como primer mandamiento."),
 ])

SE5 = modulo("se-5", "Sagrada Escritura V: Exégesis A.T. II: Profetas", "La palabra profética de Amós a Malaquías",
 "Estudio de los profetas de Israel: qué es un profeta, los profetas del siglo VIII, Jeremías, los profetas del exilio y los del posexilio, y la esperanza mesiánica. 5 unidades de 90 minutos, un taller de cierre y una evaluación.",
 "Los profetas fueron la conciencia de Israel: denunciaron la injusticia y la idolatría, consolaron en el exilio y mantuvieron viva la esperanza. En este módulo vas a conocer su mensaje en su contexto y su vigencia para hoy.",
 "Cada participante elige un profeta y prepara una «carta profética» actual: un texto breve que, inspirado en el estilo y los temas de ese profeta, denuncie una injusticia de hoy y anuncie esperanza, con al menos dos citas del libro. Se leen en el grupo y se comenta su fidelidad al profeta y a la doctrina social de la Iglesia.",
 [
  U("¿Qué es un profeta?",
    "Comprender la figura del profeta en Israel, su vocación y su misión, y la organización de los libros proféticos.",
    "Para mucha gente, un profeta es alguien que adivina el futuro. En la Biblia, un profeta es otra cosa: alguien que habla en nombre de Dios al presente de su pueblo. En esta unidad vas a conocer quiénes eran y cómo se organizan sus libros.",
    [("El que habla en nombre de Dios", "La palabra hebrea **nabí** se relaciona con «llamar» o «ser llamado». El profeta es llamado por Dios y enviado a hablar en su nombre. Sus oráculos suelen empezar con «Así dice el Señor». Más que predecir, interpreta la historia desde Dios y llama a la conversión."),
     ("La vocación", "Los relatos de vocación (Isaías 6, Jeremías 1, Ezequiel 1–3) muestran que el profeta no elige su misión: Dios lo llama, muchas veces a pesar de su resistencia. Jeremías dice: «No sé hablar, soy un muchacho»; Dios responde: «No digas que eres un muchacho: irás adonde yo te envíe»."),
     ("Profetas anteriores y posteriores", "En la Biblia hebrea, los **Profetas anteriores** son los libros de Josué, Jueces, Samuel y Reyes, donde actúan profetas como Natán, Elías y Eliseo. Los **Profetas posteriores** son los libros que llevan nombre de profeta: Isaías, Jeremías, Ezequiel y los Doce. La Biblia cristiana suma Lamentaciones, Baruc y Daniel."),
     ("Mayores y menores", "Isaías, Jeremías, Ezequiel y Daniel se llaman **profetas mayores** por la extensión de sus libros, no por su importancia. Los **doce profetas menores** (de Oseas a Malaquías) son libros más breves.")],
    ("Jeremías 1,4-10 · La vocación de Jeremías", "Dios le dice a Jeremías que lo conocía antes de formarlo en el vientre y que lo constituyó profeta de las naciones. Jeremías se resiste por su juventud. Dios toca su boca y le dice: «Pongo mis palabras en tu boca». La vocación profética es iniciativa de Dios y no depende de la edad."),
    [I("Dei Verbum 15", "La economía del Antiguo Testamento estaba ordenada a preparar y anunciar proféticamente la venida de Cristo."),
     I("Catecismo de la Iglesia Católica 64 y 2581-2584", "Por los profetas, Dios forma a su pueblo en la esperanza de la salvación; los profetas son hombres de oración que interceden y llaman a la conversión.")],
    ["¿Qué imagen tenías de los profetas?", "¿Quiénes son voces proféticas hoy?", "¿Te identificas con la resistencia de Jeremías?", "¿Qué te dice que Dios llame a un joven?"],
    "Lean en grupos los relatos de vocación de Isaías 6,1-8 y Jeremías 1,4-10. Comparen: lugar, reacción del profeta, signo de Dios y misión. Relacionen con la propia vocación de servicio.",
    "Señor, que llamaste a los profetas aunque se sentían pequeños: pon tus palabras en mi boca. Que no tenga miedo de anunciar tu verdad ni de denunciar lo que daña a tu pueblo. Amén.",
    "Piensa en una persona que haya sido «profeta» en tu vida: alguien que te dijo una verdad que necesitabas.",
    ["Explicar qué es un profeta bíblico.", "Conocer los relatos de vocación.", "Organizar los libros proféticos."],
    ("Profetas y adivinos", "La Biblia prohíbe la adivinación (Deuteronomio 18,9-14) y distingue al verdadero profeta del falso: el verdadero habla en nombre del Señor, su palabra se cumple y lleva a la fidelidad a Dios."),
    ("El profeta incómodo", "En la parroquia, una joven denuncia que una actividad excluye a los jóvenes con menos recursos. Algunos la acusan de ser conflictiva.", ["¿Qué rasgos proféticos ves en ella?", "¿Cómo discernir una crítica profética de una simple queja?"]),
    [["Nabí", "Profeta: llamado y enviado a hablar en nombre de Dios."], ["Oráculo", "Mensaje del profeta en nombre de Dios."], ["Profetas menores", "Doce libros proféticos breves."]],
    ["Pongo mis palabras en tu boca. ¿Qué palabra te pide Dios decir?", "Reza por quienes denuncian injusticias.", "Escucha esta semana una crítica sin defenderte enseguida."],
    ["Lean los relatos.", "Comparen.", "Relacionen con su vocación.", "Compartan."],
    "El profeta habla al presente en nombre de Dios."),
  U("Los profetas del siglo VIII",
    "Conocer el mensaje de Amós, Oseas, Isaías y Miqueas: justicia social, amor fiel y confianza en Dios.",
    "En el siglo VIII antes de Cristo, Israel y Judá vivían prosperidad para unos pocos y miseria para muchos, mientras el culto era abundante. Cuatro profetas alzaron la voz: Amós, Oseas, Isaías y Miqueas.",
    [("Amós: la justicia", "Pastor de Técoa, en Judá, enviado al reino del norte. Denuncia con dureza a los que «venden al justo por dinero y al pobre por un par de sandalias» (2,6) y a quienes celebran fiestas mientras oprimen. Su gran frase: «Que fluya el derecho como agua y la justicia como un torrente inagotable» (5,24)."),
     ("Oseas: el amor fiel", "Oseas vive un drama personal: su esposa le es infiel y él la sigue amando. En su experiencia descubre el amor de Dios por un pueblo infiel: «La seduciré, la llevaré al desierto y le hablaré al corazón» (2,16). Dios dice: «Quiero amor y no sacrificios» (6,6), frase que Jesús citará."),
     ("Isaías de Jerusalén", "Isaías (capítulos 1–39 en su mayor parte) recibe su vocación en el Templo ante la santidad de Dios (capítulo 6). Llama al rey a confiar en Dios y no en alianzas políticas. Anuncia el signo del **Emmanuel** (7,14) y un rey justo sobre quien reposará el Espíritu (11,1-9)."),
     ("Miqueas: lo que Dios pide", "Campesino de Moréset, denuncia a los que acaparan casas y campos. Resume la religión verdadera: «Se te ha indicado, hombre, qué es lo bueno y qué exige de ti el Señor: practicar la justicia, amar la fidelidad y caminar humildemente con tu Dios» (6,8). Anuncia que de Belén saldrá el pastor de Israel (5,1).")],
    ("Amós 5,21-24 · Que fluya la justicia", "Dios dice que detesta las fiestas y los sacrificios de un pueblo que oprime al pobre, y que no quiere oír el ruido de sus cantos. Lo que pide es que fluya el derecho como agua y la justicia como un torrente. El culto sin justicia está vacío."),
    [I("Catecismo de la Iglesia Católica 2443-2449", "Dios bendice a los que ayudan a los pobres; los profetas denuncian a quienes oprimen al pobre, y la caridad con ellos es una exigencia de la justicia."),
     I("Evangelii gaudium 187-188", "Cada cristiano y cada comunidad están llamados a ser instrumentos de Dios para la liberación y promoción de los pobres; escuchar su clamor nace de la obra liberadora de la gracia.")],
    ["¿Qué denunciaría Amós hoy en Chile?", "¿Qué te dice el amor de Dios según Oseas?", "¿Dónde confiamos más en las estrategias que en Dios?", "¿Cómo vives Miqueas 6,8?"],
    "En grupos, lean un capítulo de cada profeta (Amós 5, Oseas 11, Isaías 11, Miqueas 6) y elijan un versículo clave. Escríbanlo en un afiche junto a una situación actual a la que ilumine.",
    "Señor, que quieres amor y no sacrificios, justicia y no solo ritos: haz que nuestra fe se note en la manera de tratar a los pobres. Que practiquemos la justicia, amemos la fidelidad y caminemos humildemente contigo. Amén.",
    "Escribe una injusticia que ves en tu barrio, colegio o ciudad.",
    ["Conocer el contexto del siglo VIII.", "Distinguir el mensaje de cada profeta.", "Relacionar profecía, justicia y culto."],
    ("Isaías en tres partes", "Los estudiosos distinguen en el libro de Isaías tres grandes secciones: la del profeta del siglo VIII (1–39), la del exilio (40–55) y la del posexilio (56–66). La tradición las reunió bajo el nombre de Isaías."),
    ("Misa y justicia", "Un joven dice que en su parroquia hay muchas misas, pero nadie hace nada por las familias del campamento cercano.", ["¿Qué diría Amós?", "¿Qué paso concreto podría dar el grupo?"]),
    [["Justicia", "Relaciones rectas con Dios y con el prójimo, sobre todo el pobre."], ["Emmanuel", "Dios con nosotros (Isaías 7,14)."], ["Amor fiel", "Hesed: amor leal de Dios a su alianza."]],
    ["Que fluya la justicia. ¿Dónde está seca en tu entorno?", "Reza por los pobres de tu ciudad.", "Haz un gesto concreto de justicia."],
    ["Lean los capítulos.", "Elijan versículos.", "Hagan los afiches.", "Presenten."],
    "El culto verdadero va unido a la justicia."),
  U("Jeremías y la caída de Jerusalén",
    "Conocer la vida y el mensaje de Jeremías, profeta de la crisis y de la nueva alianza.",
    "Jeremías vivió los años más dramáticos de Judá: la caída de Jerusalén y el exilio. Su libro deja ver su sufrimiento personal como pocos. Y en medio de la catástrofe anuncia algo inesperado: una nueva alianza.",
    [("Un profeta en tiempos de crisis", "Jeremías actuó desde fines del siglo VII hasta después de la caída de Jerusalén en el **587 o 586 antes de Cristo**. Anunció que confiar en el Templo como garantía mágica era un engaño (capítulo 7) y que Babilonia sería instrumento del castigo. Por eso lo trataron de traidor."),
     ("Las confesiones", "En varios pasajes (por ejemplo 15,10-21 y 20,7-18) Jeremías se queja ante Dios de su sufrimiento: «Me sedujiste, Señor, y me dejé seducir». Son llamadas sus **confesiones**. Muestran a un profeta humano, que sufre su misión y que, aun así, no puede dejar de anunciar: la palabra es como un fuego en sus huesos."),
     ("Acciones simbólicas", "Jeremías comunica también con gestos: un cinturón podrido, una vasija rota, un yugo sobre el cuello. Al final compra un campo cuando Jerusalén está sitiada (capítulo 32), como signo de esperanza: «Todavía se comprarán casas y campos en esta tierra»."),
     ("La nueva alianza", "En el corazón de la crisis anuncia: «Llegarán días en que haré una alianza nueva… pondré mi ley en su interior y la escribiré en su corazón» (31,31-34). Jesús retoma estas palabras en la Última Cena: «Esta copa es la nueva alianza en mi sangre».")],
    ("Jeremías 31,31-34 · La nueva alianza", "Dios promete una alianza distinta a la del Sinaí, que el pueblo rompió: escribirá su ley en el corazón, todos lo conocerán y perdonará sus culpas. La Carta a los Hebreos cita este texto completo para hablar de la obra de Cristo."),
    [I("Catecismo de la Iglesia Católica 64 y 715", "Los profetas anuncian una redención radical del pueblo y una nueva alianza destinada a todas las naciones, escrita en los corazones."),
     I("Catecismo de la Iglesia Católica 2584", "Los profetas, en su soledad con Dios, sacan luz y fuerza para su misión; su oración es un combate de la fe.")],
    ["¿Qué te dicen las quejas de Jeremías sobre tu oración?", "¿En qué «templos» ponemos falsas seguridades?", "¿Qué gesto de esperanza podrías hacer en una crisis?", "¿Qué significa que la ley esté escrita en el corazón?"],
    "Lean Jeremías 20,7-9 y 32,6-15. Cada participante escribe su propia «confesión» a Dios sobre una dificultad en su servicio, y un gesto concreto de esperanza que hará.",
    "Señor, que sedujiste a Jeremías y le diste tu palabra como fuego: cuando el servicio me cuesta, déjame quejarme contigo sin dejar de seguirte. Escribe tu ley en mi corazón. Amén.",
    "Escribe una frase de queja sincera a Dios sobre algo que te cuesta.",
    ["Conocer el contexto de Jeremías.", "Comprender sus confesiones y acciones simbólicas.", "Relacionar la nueva alianza con la Eucaristía."],
    ("Lamentaciones", "El libro de las Lamentaciones, atribuido por la tradición a Jeremías, llora la destrucción de Jerusalén con cinco poemas. Se lee en la liturgia de Semana Santa."),
    ("Dirigente cansado", "Un dirigente con años de servicio confiesa que ya no siente nada y que sigue solo por obligación.", ["¿Qué le diría Jeremías?", "¿Qué acompañamiento necesita?"]),
    [["Confesiones", "Quejas personales de Jeremías ante Dios."], ["Acción simbólica", "Gesto profético que comunica un mensaje."], ["Nueva alianza", "Alianza escrita en el corazón (Jeremías 31)."]],
    ["Me sedujiste, Señor. ¿Cómo te sedujo Dios a ti?", "Reza la oración de Jeremías 20,7-9.", "Haz un gesto de esperanza en una situación difícil."],
    ["Lean los textos.", "Escriban su confesión.", "Definan un gesto.", "Compartan."],
    "En medio de la crisis, Dios promete una alianza nueva."),
  U("Profetas del exilio: Ezequiel y el Segundo Isaías",
    "Conocer el mensaje de consuelo y esperanza de Ezequiel y de Isaías 40–55, incluidos los cantos del Siervo.",
    "En el exilio de Babilonia, cuando todo parecía perdido, Dios suscitó profetas de consuelo. Ezequiel anunció un corazón nuevo y huesos que reviven. Un profeta anónimo, cuyo mensaje está en Isaías 40–55, anunció un nuevo éxodo y presentó la misteriosa figura del Siervo sufriente.",
    [("Ezequiel: corazón nuevo", "Sacerdote deportado a Babilonia en el 597. Tiene visiones impresionantes de la gloria de Dios. Anuncia: «Les daré un corazón nuevo y pondré en ustedes un espíritu nuevo; quitaré su corazón de piedra y les daré un corazón de carne» (36,26). Ve un valle de **huesos secos** que reviven por el espíritu de Dios (37): Israel volverá a vivir."),
     ("Ezequiel: el buen pastor", "En el capítulo 34 denuncia a los malos pastores que se aprovechan del rebaño y anuncia que Dios mismo pastoreará a sus ovejas: buscará a la perdida, vendará a la herida. Jesús se presentará como el buen pastor (Juan 10)."),
     ("Segundo Isaías: consuelo", "Isaías 40 comienza: «Consuelen, consuelen a mi pueblo». El profeta anuncia el fin del exilio como un **nuevo éxodo**, a través del desierto. Insiste en que hay un solo Dios, creador y señor de la historia, frente a los ídolos de Babilonia. Ciro aparece como instrumento de Dios."),
     ("Los cantos del Siervo", "Cuatro poemas (42,1-9; 49,1-6; 50,4-11; 52,13–53,12) presentan a un **Siervo del Señor** que trae justicia a las naciones con mansedumbre y que sufre por los pecados de otros: «Él fue traspasado por nuestras rebeldías… por sus heridas fuimos sanados». Los primeros cristianos vieron en él a Jesús, y la liturgia lo lee el Viernes Santo.")],
    ("Ezequiel 37,1-14 · Los huesos secos", "El profeta es llevado a un valle lleno de huesos secos. Dios le pregunta si pueden revivir y le manda profetizar. Los huesos se juntan, se cubren de carne y el espíritu entra en ellos. Dios dice: «Abriré sus tumbas… pondré mi espíritu en ustedes y vivirán». Ninguna situación está tan muerta que Dios no pueda resucitarla."),
    [I("Catecismo de la Iglesia Católica 601 y 713", "Los cantos del Siervo anuncian el sentido de la pasión de Jesús; el Mesías es presentado como el Siervo sobre quien reposa el Espíritu.")],
    ["¿Qué «huesos secos» ves en tu comunidad?", "¿Qué te consuela de Isaías 40?", "¿Cómo te ayuda Isaías 53 a entender la pasión de Jesús?", "¿Qué malos pastoreos denunciaría hoy Ezequiel?"],
    "Lean en voz alta el cuarto canto del Siervo (Isaías 52,13–53,12) y después el relato de la pasión de Marcos 15. Anoten las coincidencias y conversen cómo la Iglesia leyó este texto.",
    "Señor, que conviertes los huesos secos en un pueblo vivo y das un corazón nuevo: sopla tu Espíritu sobre lo que está muerto en mí y en mi comunidad. Gracias por Jesús, el Siervo que cargó con nuestros dolores. Amén.",
    "Escribe algo de tu vida o tu comunidad que sientes «seco» o sin vida.",
    ["Conocer el mensaje de Ezequiel.", "Comprender el consuelo del Segundo Isaías.", "Relacionar los cantos del Siervo con la pasión de Jesús."],
    ("¿Quién es el Siervo?", "En su contexto, el Siervo puede representar a Israel o a una figura individual; los estudiosos discuten. Los cristianos, desde Hechos 8, lo leen a la luz de Jesús, en quien la figura alcanza su sentido pleno."),
    ("La comunidad que se apaga", "Un grupo juvenil quedó con tres miembros y el ánimo por el suelo. Los dirigentes piensan cerrarlo.", ["¿Qué diría Ezequiel 37?", "¿Qué pasos concretos podrían dar?"]),
    [["Corazón nuevo", "Promesa de transformación interior (Ezequiel 36)."], ["Segundo Isaías", "Isaías 40–55, profeta del exilio."], ["Siervo del Señor", "Figura de los cuatro cantos de Isaías."]],
    ["Huesos secos, escuchen la palabra del Señor. ¿Qué necesita escuchar tu corazón?", "Reza Isaías 40,1-11.", "Consuela esta semana a alguien que está desanimado."],
    ["Lean el canto del Siervo.", "Lean la pasión.", "Anoten coincidencias.", "Conversen."],
    "Ninguna situación está tan muerta que Dios no pueda devolverle la vida."),
  U("Profetas después del exilio y la esperanza mesiánica",
    "Conocer a los profetas del posexilio, la apocalíptica de Daniel y la esperanza mesiánica que prepara el Nuevo Testamento.",
    "Después del regreso, la realidad fue más pobre de lo esperado. Los profetas de este tiempo animaron la reconstrucción, criticaron la tibieza y mantuvieron viva la esperanza de un tiempo nuevo. Así preparan el Nuevo Testamento.",
    [("Ageo, Zacarías y Malaquías", "- **Ageo** y **Zacarías** animan la reconstrucción del Templo hacia el 520 antes de Cristo. Zacarías anuncia un rey humilde montado en un asno (9,9), texto que los evangelios relacionan con la entrada de Jesús en Jerusalén.\n- **Malaquías** critica un culto rutinario y anuncia que Dios enviará a su mensajero, a Elías, antes del día del Señor (3,1.23). Los evangelios lo relacionan con Juan Bautista."),
     ("Tercer Isaías y Joel", "Isaías 56–66 abre el Templo a los extranjeros (56,7: «casa de oración para todos los pueblos») y anuncia cielos nuevos y tierra nueva. **Joel** anuncia que Dios derramará su Espíritu sobre todos: hijos e hijas profetizarán (3,1-2). Pedro cita este texto en Pentecostés."),
     ("Jonás", "El libro de Jonás es un relato didáctico sobre un profeta que huye de su misión porque no quiere que Dios perdone a Nínive, ciudad enemiga. Termina con una pregunta de Dios sobre su compasión. Es una crítica al nacionalismo estrecho y un anuncio de la misericordia universal."),
     ("Daniel y la apocalíptica", "El libro de Daniel, en su forma final, se escribió en la crisis de los macabeos (siglo II antes de Cristo). Sus visiones usan un lenguaje simbólico, **apocalíptico**, para afirmar que Dios vencerá a los imperios opresores. Allí aparece la figura del **Hijo del hombre** (7,13-14), título que Jesús usó para sí mismo.")],
    ("Daniel 7,13-14 · El Hijo del hombre", "En una visión nocturna, Daniel ve venir sobre las nubes del cielo a uno como un hijo de hombre, que recibe del Anciano poder, honor y un reino que no será destruido. Jesús usó este título en los evangelios, especialmente ante el Sanedrín (Marcos 14,62)."),
    [I("Catecismo de la Iglesia Católica 711-716", "Los profetas anuncian la venida del Mesías y la efusión del Espíritu sobre todos en los tiempos mesiánicos."),
     I("Dei Verbum 16", "Dios dispuso sabiamente que el Nuevo Testamento estuviera escondido en el Antiguo y el Antiguo manifiesto en el Nuevo.")],
    ["¿Qué te dice la entrada de Jesús en un asno, según Zacarías?", "¿Por qué Jonás no quería que Nínive se salvara?", "¿Qué esperanza necesita hoy tu comunidad?", "¿Cómo leerías Daniel sin convertirlo en un calendario del fin del mundo?"],
    "Hagan una tabla con cinco textos proféticos citados en el Nuevo Testamento (Isaías 7,14; Miqueas 5,1; Zacarías 9,9; Malaquías 3,1; Joel 3,1-2), indicando dónde se citan y qué dicen de Jesús o de la Iglesia.",
    "Dios fiel, que mantuviste viva la esperanza de tu pueblo: derrama tu Espíritu sobre nosotros, abre nuestra comunidad a todos los pueblos y prepara nuestros corazones para recibir a tu Hijo, el Mesías humilde. Amén.",
    "Escribe una esperanza que tienes para tu comunidad en los próximos años.",
    ["Conocer a los profetas del posexilio.", "Comprender el género apocalíptico de Daniel.", "Relacionar textos proféticos con el Nuevo Testamento."],
    ("El cierre de los profetas", "En la Biblia cristiana, el Antiguo Testamento termina con Malaquías y el anuncio de Elías. El Nuevo comienza con los evangelios y Juan Bautista. Así el orden mismo de los libros expresa la continuidad entre ambos testamentos."),
    ("El Jonás de hoy", "En el grupo, algunos no quieren invitar a jóvenes de un colegio rival porque «son pesados».", ["¿Qué enseñanza tiene el libro de Jonás?", "¿Cómo lo aplicarías?"]),
    [["Posexilio", "Período después del regreso de Babilonia."], ["Apocalíptica", "Género simbólico que revela la victoria final de Dios."], ["Hijo del hombre", "Figura de Daniel 7 que Jesús aplicó a sí mismo."]],
    ["Derramaré mi Espíritu sobre todos. ¿Qué don te da el Espíritu?", "Reza por la paz entre los pueblos.", "Invita esta semana a alguien que no suele ser invitado."],
    ["Busquen los textos.", "Ubiquen las citas.", "Completen la tabla.", "Compartan."],
    "Los profetas mantienen viva la esperanza que se cumple en Jesús."),
 ],
 [P("¿Qué es principalmente un profeta bíblico?", ["Un adivino del futuro", "Alguien llamado a hablar en nombre de Dios al presente de su pueblo", "Un sacerdote del Templo"], 1, "Interpreta la historia desde Dios."),
  P("¿Por qué se llaman «mayores» algunos profetas?", ["Por su importancia", "Por la extensión de sus libros", "Por su edad"], 1, "Isaías, Jeremías, Ezequiel y Daniel."),
  P("¿Qué profeta dijo «que fluya el derecho como agua»?", ["Oseas", "Amós", "Malaquías"], 1, "Amós 5,24."),
  P("¿Qué resume Miqueas 6,8?", ["Practicar la justicia, amar la fidelidad y caminar humildemente con Dios", "Ofrecer muchos sacrificios", "Construir el Templo"], 0, "Lo que Dios pide."),
  P("¿Qué anuncia Jeremías 31,31-34?", ["La destrucción del mundo", "Una nueva alianza escrita en el corazón", "El regreso de Elías"], 1, "Jesús la retoma en la Última Cena."),
  P("¿Qué imagen usa Ezequiel 37?", ["Una escalera", "Un valle de huesos secos que reviven", "Una zarza ardiente"], 1, "Dios devuelve la vida a su pueblo."),
  P("¿Dónde están los cantos del Siervo?", ["Isaías 40–55", "Jeremías 1–10", "Daniel 7"], 0, "Isaías 42; 49; 50; 52–53."),
  P("¿En qué contexto se escribió la forma final del libro de Daniel?", ["El exilio", "La crisis de los macabeos", "El tiempo de David"], 1, "Siglo II antes de Cristo."),
 ])

SE6 = modulo("se-6", "Sagrada Escritura VI: Exégesis N.T. II: San Pablo", "La vida de Pablo y sus cartas",
 "Estudio de san Pablo: su vida y misión, el género y la cronología de sus cartas, y los grandes temas de Gálatas, Romanos, Corintios, Filipenses y Tesalonicenses. 5 unidades de 90 minutos, un taller de cierre y una evaluación.",
 "Pablo es el gran misionero de la Iglesia naciente y el primer escritor cristiano. Sus cartas, escritas a comunidades concretas, siguen iluminando la fe y la vida de la Iglesia. En este módulo vas a conocerlo y a leer sus textos más importantes.",
 "Cada participante escribe una carta al estilo de Pablo dirigida a su propia comunidad o grupo: saludo, acción de gracias, cuerpo (un problema real y una enseñanza desde la fe), exhortación y despedida. Debe incluir al menos tres citas de cartas paulinas bien usadas. Se leen en grupos y se comentan.",
 [
  U("Pablo: vida y misión",
    "Conocer la vida de Pablo, su conversión y sus viajes misioneros.",
    "Pablo pasó de perseguir a los cristianos a ser el gran apóstol de los paganos. Conocer su vida ayuda a entender sus cartas, escritas en medio de viajes, prisiones y conflictos.",
    [("Saulo de Tarso", "Nació en **Tarso de Cilicia** (actual Turquía), en una familia judía de la diáspora con ciudadanía romana. Se formó como **fariseo**, celoso de la Ley. Hablaba griego y conocía la cultura de su tiempo. Persiguió a los primeros cristianos."),
     ("El encuentro en Damasco", "Camino a Damasco, hacia el año 33-36, se encuentra con Cristo resucitado (Hechos 9; Gálatas 1,15-16). Pablo no lo describe como un cambio de religión, sino como un **llamado**: Dios le revela a su Hijo para que lo anuncie a los paganos. Desde entonces, todo lo considera pérdida frente a conocer a Cristo."),
     ("Los viajes misioneros", "Hechos narra tres grandes viajes misioneros por Asia Menor y Grecia, fundando comunidades en ciudades como Filipos, Tesalónica, Corinto y Éfeso. Pablo trabaja con sus manos (fabricante de tiendas) para no ser una carga, y trabaja en equipo: Bernabé, Silas, Timoteo, Tito, Priscila y Áquila."),
     ("Prisión y muerte", "Arrestado en Jerusalén, apela al César y es llevado a Roma. Según la tradición, murió mártir en Roma bajo Nerón, hacia el año 64-67, decapitado como ciudadano romano. Su tumba se venera en la basílica de San Pablo Extramuros.")],
    ("Gálatas 1,11-17 · Me reveló a su Hijo", "Pablo cuenta su vocación: era un perseguidor celoso, pero Dios, que lo eligió desde el seno materno, le reveló a su Hijo para que lo anunciara a los paganos. Pablo insiste en que su Evangelio no viene de hombres, sino de una revelación de Jesucristo."),
    [I("Catecismo de la Iglesia Católica 442 y 659", "La aparición de Cristo resucitado a Pablo en el camino de Damasco lo constituyó apóstol; su conversión es el encuentro con el Hijo de Dios."),
     I("Verbum Domini 48", "Los santos, como Pablo, muestran que la Palabra de Dios transforma la vida de quien la acoge.")],
    ["¿Qué te impresiona de la vida de Pablo?", "¿Has tenido algún «Damasco», un encuentro que cambió tu vida?", "¿Qué te enseña Pablo sobre el trabajo en equipo?", "¿Qué lugar tuvieron las mujeres en sus comunidades?"],
    "Sigan en un mapa los tres viajes misioneros y el viaje a Roma. En cada ciudad anoten qué pasó según Hechos y qué carta se relaciona. Calculen distancias aproximadas.",
    "Señor Jesús, que te revelaste a Pablo en el camino de Damasco: revélate también a mí. Que, como él, considere todo como pérdida frente a conocerte, y que anuncie tu Evangelio con pasión y en equipo. Amén.",
    "Escribe en tres frases tu propio encuentro con Cristo.",
    ["Conocer la biografía de Pablo.", "Comprender su conversión como llamado.", "Ubicar sus viajes y comunidades."],
    ("Pablo y las mujeres", "En sus cartas Pablo nombra a muchas colaboradoras: Febe, diaconisa de Céncreas; Prisca, colaboradora; Junia, «ilustre entre los apóstoles»; Evodia y Síntique, que lucharon con él por el Evangelio (Romanos 16; Filipenses 4,2-3)."),
    ("El perseguidor", "Un joven del grupo se burlaba antes de los que iban a la parroquia y ahora quiere ser dirigente. Algunos desconfían de él.", ["¿Qué enseña la historia de Pablo?", "¿Cómo acompañarlo?"]),
    [["Damasco", "Lugar del encuentro de Pablo con Cristo."], ["Apóstol de los gentiles", "Título de Pablo como enviado a los paganos."], ["Viajes misioneros", "Recorridos de Pablo fundando comunidades."]],
    ["Me reveló a su Hijo. ¿Cómo se te ha revelado Jesús?", "Reza por los misioneros.", "Lee Filipenses completo esta semana."],
    ["Abran el mapa.", "Sigan los viajes.", "Relacionen las cartas.", "Presenten."],
    "Pablo no cambió de religión: fue alcanzado por Cristo."),
  U("Las cartas de Pablo: género, cronología y autoría",
    "Conocer la estructura de las cartas paulinas, su orden aproximado y la distinción entre cartas auténticas y de la tradición paulina.",
    "Las cartas de Pablo no son tratados teológicos: son respuestas a problemas reales de comunidades concretas. Para entenderlas hay que saber cómo se escribía una carta en su época y en qué momento escribió cada una.",
    [("La forma de una carta", "Las cartas de Pablo siguen el modelo de su tiempo, con su sello propio:\n\n1. **Encabezado:** remitente, destinatarios y saludo («gracia y paz»).\n2. **Acción de gracias** por la comunidad.\n3. **Cuerpo:** enseñanza y respuesta a problemas.\n4. **Exhortación:** consecuencias para la vida.\n5. **Despedida:** saludos y bendición.\n\nPablo solía dictar y añadía un saludo de su puño y letra."),
     ("Cronología aproximada", "Las cartas se escribieron entre los años **50 y 60** aproximadamente. Un orden probable de las indiscutidas:\n\n- 1 Tesalonicenses (hacia el 50).\n- 1 y 2 Corintios, Gálatas, Filipenses y Filemón (mediados de los 50).\n- Romanos (hacia el 56-57).\n\nNo están ordenadas así en la Biblia, sino por extensión, de la más larga a la más breve."),
     ("Cartas auténticas y tradición paulina", "Los estudiosos coinciden en que Pablo escribió personalmente siete cartas: **Romanos, 1 y 2 Corintios, Gálatas, Filipenses, 1 Tesalonicenses y Filemón**. Sobre Efesios, Colosenses y 2 Tesalonicenses hay discusión. Las **pastorales** (1 y 2 Timoteo, Tito) se consideran en general de discípulos posteriores que escribieron en su nombre, práctica común en la Antigüedad."),
     ("Lo que no cambia", "La discusión sobre autoría no afecta la inspiración: todas las cartas forman parte del canon y son Palabra de Dios. Distinguir ayuda a ver cómo la tradición paulina se desarrolló en las comunidades después de Pablo.")],
    ("1 Tesalonicenses 1,1-10 · El escrito cristiano más antiguo", "Pablo saluda a la comunidad de Tesalónica y da gracias por su fe activa, su amor esforzado y su esperanza constante. Recuerda cómo recibieron la Palabra en medio de tribulaciones. Es probablemente el escrito más antiguo del Nuevo Testamento, hacia el año 50."),
    [I("Dei Verbum 20", "El canon del Nuevo Testamento contiene, además de los evangelios, las cartas de Pablo y otros escritos apostólicos, que confirman lo que se refiere a Cristo y explican su doctrina."),
     I("Catecismo de la Iglesia Católica 1813", "Las virtudes teologales, fe, esperanza y caridad, que Pablo nombra desde su primera carta, fundan y animan el obrar del cristiano.")],
    ["¿Qué te dice que las cartas respondan a problemas concretos?", "¿Te cambia algo saber que algunas cartas son de discípulos de Pablo?", "¿Qué problemas de tu comunidad abordaría Pablo?", "¿Por qué crees que la fe, la esperanza y el amor aparecen desde el principio?"],
    "Analicen la estructura de la carta a Filemón (es breve): identifiquen encabezado, acción de gracias, cuerpo, exhortación y despedida. Luego conversen qué problema concreto aborda y qué enseñanza deja sobre la dignidad.",
    "Señor, que inspiraste a Pablo a escribir a comunidades concretas: que sus palabras lleguen hoy a mi comunidad y me ayuden a vivir la fe activa, el amor esforzado y la esperanza constante. Amén.",
    "Escribe a quién te gustaría escribirle una carta de ánimo en la fe.",
    ["Reconocer la estructura de una carta paulina.", "Ubicar las cartas en una cronología aproximada.", "Distinguir cartas auténticas y de la tradición paulina."],
    ("Pseudonimia", "En la Antigüedad era aceptado que un discípulo escribiera en nombre de su maestro para actualizar su enseñanza. No se consideraba un engaño, sino una forma de fidelidad a la tradición del maestro."),
    ("Filemón y Onésimo", "Un participante pregunta por qué Pablo no condenó directamente la esclavitud en la carta a Filemón.", ["¿Qué dice realmente la carta?", "¿Qué semilla deja para el futuro?"]),
    [["Carta auténtica", "Escrita por el mismo Pablo."], ["Cartas pastorales", "1 y 2 Timoteo y Tito."], ["Pseudonimia", "Escribir en nombre de un maestro."]],
    ["Fe activa, amor esforzado, esperanza constante. ¿Cuál necesitas hoy?", "Agradece por tu comunidad, como Pablo.", "Escribe una carta de ánimo a alguien."],
    ["Lean Filemón.", "Identifiquen las partes.", "Conversen el problema.", "Compartan."],
    "Las cartas de Pablo son Palabra de Dios para comunidades reales."),
  U("Gálatas y Romanos: justificados por la fe",
    "Comprender el tema de la justificación por la fe en Cristo y la libertad cristiana en Gálatas y Romanos.",
    "Gálatas y Romanos tratan una pregunta decisiva: ¿cómo nos salva Dios? ¿Por cumplir la Ley o por la fe en Cristo? Pablo responde con fuerza: somos justificados por la gracia, mediante la fe, y esa fe se expresa en el amor.",
    [("El conflicto de Galacia", "Algunos predicadores decían a los gálatas, de origen pagano, que para ser cristianos debían circuncidarse y cumplir la Ley de Moisés. Pablo reacciona con pasión: eso sería negar que Cristo basta. «Si la justificación viniera por la Ley, Cristo habría muerto inútilmente» (Gálatas 2,21)."),
     ("Justificados por la fe", "Ser **justificado** significa ser hecho justo, puesto en relación correcta con Dios. Pablo afirma que esto es **don gratuito** de Dios, recibido por la **fe en Cristo**, no un premio por nuestras obras. Abraham es el ejemplo: creyó y le fue tenido en cuenta como justicia."),
     ("La fe que actúa por el amor", "Esto no significa que las obras no importen. Pablo habla de «la fe que actúa por medio del amor» (Gálatas 5,6). La libertad cristiana no es para hacer lo que uno quiere, sino para servirse por amor. El Espíritu produce frutos: amor, alegría, paz, paciencia, bondad (5,22-23)."),
     ("Romanos: el Evangelio para todos", "Romanos es la carta más extensa y sistemática. Pablo la escribe a una comunidad que no fundó, antes de ir a Roma. Muestra que todos, judíos y paganos, necesitan la gracia (1–3), que somos justificados por la fe (3–5), que vivimos según el Espíritu como hijos de Dios (8) y que nada puede separarnos del amor de Dios en Cristo (8,38-39). Los capítulos 9–11 reflexionan sobre Israel, y 12–15 sobre la vida cristiana.")],
    ("Romanos 8,14-17.31-39 · Nada podrá separarnos", "Los que se dejan guiar por el Espíritu son hijos de Dios y pueden llamarlo «Abbá, Padre». Si Dios está con nosotros, ¿quién contra nosotros? Ni la muerte ni la vida ni ninguna criatura podrá separarnos del amor de Dios manifestado en Cristo Jesús."),
    [I("Catecismo de la Iglesia Católica 1987-1995", "La gracia del Espíritu Santo tiene el poder de justificarnos; la justificación es obra de la misericordia de Dios y se concede por el bautismo, sacramento de la fe."),
     I("Catecismo de la Iglesia Católica 1832", "Los frutos del Espíritu son perfecciones que forma en nosotros el Espíritu Santo.")],
    ["¿Sientes a veces que tienes que «ganarte» el amor de Dios?", "¿Qué significa para ti la libertad cristiana?", "¿Qué fruto del Espíritu ves en tu vida y cuál te falta?", "¿Qué te dice Romanos 8,38-39?"],
    "En grupos, lean Gálatas 5,1.13-26 y elaboren dos columnas: «obras de la carne» y «frutos del Espíritu». Luego, cada uno elige un fruto para cultivar en el próximo mes y escribe cómo.",
    "Padre, gracias por justificarme gratuitamente en Cristo. No tengo que ganarme tu amor: ya me amas. Que tu Espíritu me haga libre para servir por amor y dé en mí sus frutos. Nada me separará de tu amor. Amén.",
    "Completa: «Siento que tengo que ganarme el amor de Dios cuando…».",
    ["Explicar la justificación por la fe.", "Relacionar fe, libertad y amor.", "Conocer la estructura de Romanos."],
    ("Católicos y luteranos", "En 1999, la Iglesia católica y la Federación Luterana Mundial firmaron la Declaración conjunta sobre la doctrina de la justificación, reconociendo un consenso en las verdades básicas: somos aceptados por Dios por gracia, mediante la fe en Cristo, no por nuestros méritos."),
    ("La competencia espiritual", "En un grupo, algunos jóvenes comparan cuántas misas o retiros han hecho y miran en menos a los que hacen menos.", ["¿Qué diría Pablo?", "¿Cómo orientarías al grupo?"]),
    [["Justificación", "Ser hecho justo por gracia, mediante la fe."], ["Gracia", "Don gratuito de Dios."], ["Frutos del Espíritu", "Amor, alegría, paz y demás (Gálatas 5,22-23)."]],
    ["Nada podrá separarnos del amor de Dios. ¿Qué miedo te separa?", "Reza llamando a Dios «Abbá».", "Sirve a alguien gratuitamente esta semana."],
    ["Lean Gálatas 5.", "Hagan las columnas.", "Elijan un fruto.", "Escriban cómo cultivarlo."],
    "No nos ganamos el amor de Dios: lo recibimos y respondemos amando."),
  U("Corintios: comunidad, carismas y amor",
    "Conocer los problemas de la comunidad de Corinto y las respuestas de Pablo sobre la unidad, la Eucaristía, los carismas, el amor y la resurrección.",
    "Corinto era una ciudad portuaria, rica, diversa y conflictiva. Su comunidad cristiana tenía divisiones, escándalos y preguntas. Las cartas de Pablo a los corintios muestran cómo se acompaña a una comunidad real.",
    [("Divisiones", "Los corintios se dividían en bandos: «Yo soy de Pablo», «yo de Apolo», «yo de Pedro». Pablo responde: ¿acaso Cristo está dividido? Anuncia la **sabiduría de la cruz**, que parece locura al mundo pero es fuerza de Dios (1 Corintios 1,18-25)."),
     ("La Eucaristía y los pobres", "En la cena del Señor, los ricos comían y bebían mientras los pobres pasaban hambre. Pablo les recuerda la tradición de la Última Cena (11,23-26), el texto más antiguo sobre la institución de la Eucaristía, y les dice que comer el pan sin discernir el Cuerpo, que es también la comunidad, es comer indignamente."),
     ("Carismas y amor", "Pablo compara a la comunidad con un **cuerpo**: muchos miembros con distintos dones, todos necesarios (capítulo 12). Pero el camino más excelente es el **amor**: «El amor es paciente, es servicial; el amor no es envidioso…» (capítulo 13). Sin amor, los dones no sirven de nada."),
     ("La resurrección", "Algunos negaban la resurrección de los muertos. En el capítulo 15, Pablo transmite el credo más antiguo: Cristo murió, fue sepultado, resucitó al tercer día y se apareció a Pedro, a los Doce y a muchos más. «Si Cristo no resucitó, vana es nuestra fe». La segunda carta muestra a un Pablo frágil: «Mi fuerza se manifiesta en la debilidad» (2 Corintios 12,9).")],
    ("1 Corintios 13,1-13 · El himno al amor", "Aunque hablara las lenguas de los ángeles, si no tengo amor, no soy nada. El amor es paciente y servicial, no busca su propio interés, todo lo excusa, todo lo cree, todo lo espera, todo lo soporta. Ahora permanecen la fe, la esperanza y el amor, pero el más grande es el amor."),
    [I("Catecismo de la Iglesia Católica 1822-1829", "La caridad es la virtud teologal por la que amamos a Dios sobre todas las cosas y al prójimo por amor de Dios; es el vínculo de la perfección."),
     I("Catecismo de la Iglesia Católica 1396-1398", "La Eucaristía hace la Iglesia y compromete en favor de los pobres.")],
    ["¿Qué divisiones hay en tu comunidad?", "¿Cómo se relacionan Eucaristía y pobres?", "¿Qué don tienes para la comunidad?", "¿Qué frase de 1 Corintios 13 te interpela más?"],
    "Hagan una dinámica del cuerpo: cada participante escribe en una tarjeta el don que reconoce en otro compañero y se la entrega. Luego lean juntos 1 Corintios 12,12-27 y conversen qué miembros de su comunidad suelen ser olvidados.",
    "Señor, que nos haces un solo cuerpo con muchos miembros: líbranos de las divisiones. Que nuestros dones sirvan a todos, que no olvidemos a los pobres en la mesa de la Eucaristía y que el amor sea siempre nuestro camino. Amén.",
    "Escribe un don que reconoces en ti y otro que reconoces en alguien de tu comunidad.",
    ["Conocer la situación de la comunidad de Corinto.", "Comprender la enseñanza de Pablo sobre unidad, Eucaristía y carismas.", "Reconocer el credo de 1 Corintios 15."],
    ("El credo más antiguo", "1 Corintios 15,3-5 es probablemente la fórmula de fe cristiana más antigua que conservamos. Pablo dice que la recibió y la transmite, lo que indica que circulaba pocos años después de la Pascua."),
    ("Los fans del dirigente", "En una parroquia, los jóvenes se dividen entre los que siguen a un dirigente carismático y los que siguen a otro.", ["¿Qué diría Pablo en 1 Corintios 1–3?", "¿Qué podrían hacer los dirigentes?"]),
    [["Carisma", "Don del Espíritu para el bien común."], ["Cuerpo de Cristo", "La comunidad unida en la diversidad."], ["Sabiduría de la cruz", "La lógica de Dios que parece locura al mundo."]],
    ["El más grande es el amor. ¿Dónde te falta amor?", "Reza 1 Corintios 13 poniendo tu nombre en lugar de «el amor».", "Reconcíliate con alguien de tu comunidad."],
    ["Escriban los dones.", "Entréguenlos.", "Lean 1 Corintios 12.", "Conversen."],
    "Sin amor, los dones no sirven de nada."),
  U("Filipenses, Tesalonicenses y la esperanza",
    "Conocer el mensaje de Filipenses y 1 Tesalonicenses, y tener una visión general de las cartas de la cautividad y las pastorales.",
    "Algunas cartas de Pablo muestran su lado más afectuoso: Filipenses, escrita desde la prisión, está llena de alegría; 1 Tesalonicenses consuela ante la muerte. En esta unidad cerramos el recorrido por Pablo y miramos las cartas de su tradición.",
    [("Filipenses: la alegría", "Escrita desde la cárcel, Filipenses repite la palabra **alegría**: «Alégrense siempre en el Señor, se lo repito: alégrense» (4,4). En el capítulo 2 está el himno de Cristo que se despojó de sí mismo (2,6-11). Pablo invita a tener los mismos sentimientos de Cristo y agradece la ayuda de una comunidad que lo quiere."),
     ("1 Tesalonicenses: la esperanza", "Los tesalonicenses estaban angustiados porque algunos habían muerto antes de la venida del Señor. Pablo les dice: «No se entristezcan como los que no tienen esperanza» (4,13). Los que murieron en Cristo resucitarán, y estaremos siempre con el Señor."),
     ("Colosenses y Efesios", "Llamadas, junto con Filemón, **cartas de la cautividad**. Contemplan a Cristo como cabeza de la Iglesia y de toda la creación (Colosenses 1,15-20) y la Iglesia como cuerpo y esposa de Cristo, donde judíos y paganos son un solo pueblo (Efesios 2). Efesios 4 habla de la unidad y de los ministerios."),
     ("Las cartas pastorales", "1 y 2 Timoteo y Tito se dirigen a responsables de comunidades. Tratan de la organización de la Iglesia, la sana doctrina y el cuidado de los ministros. Son útiles para pensar el servicio de los agentes pastorales: «Que nadie te menosprecie por ser joven; sé ejemplo para los creyentes» (1 Timoteo 4,12).")],
    ("Filipenses 2,1-11 · Los sentimientos de Cristo", "Pablo pide a los filipenses tener un mismo sentir y no hacer nada por rivalidad, sino con humildad. Luego canta a Cristo, que siendo de condición divina se despojó, tomó la condición de siervo y se humilló hasta la cruz; por eso Dios lo exaltó. La vida cristiana es tener los sentimientos de Cristo."),
    [I("Catecismo de la Iglesia Católica 1005-1014", "Para resucitar con Cristo es necesario morir con Cristo; la muerte cristiana es participación en la muerte del Señor y paso a la vida."),
     I("Evangelii gaudium 1-2", "La alegría del Evangelio llena el corazón y la vida entera de los que se encuentran con Jesús.")],
    ["¿Cómo puede Pablo hablar de alegría desde la cárcel?", "¿Qué sentimientos de Cristo te cuesta tener?", "¿Cómo acompañarías a alguien que perdió a un ser querido, según 1 Tesalonicenses 4?", "¿Qué te dicen las pastorales sobre tu servicio?"],
    "Cada participante elige una carta breve (Filipenses, 1 Tesalonicenses, Colosenses, Tito o Filemón), la lee completa y comparte con el grupo una frase que llevaría a su servicio pastoral.",
    "Señor Jesús, que te despojaste de ti mismo por amor: dame tus sentimientos. Que viva con alegría aun en la dificultad, con esperanza ante la muerte y con humildad en el servicio. Amén.",
    "Escribe una razón para alegrarte hoy, aunque estés pasando por algo difícil.",
    ["Conocer el mensaje de Filipenses y 1 Tesalonicenses.", "Tener una visión de las cartas de la cautividad y las pastorales.", "Aplicar la enseñanza paulina al servicio pastoral."],
    ("Alegría y sufrimiento", "La alegría cristiana no es ausencia de problemas. Pablo escribe Filipenses encarcelado, sin saber si lo matarán. Su alegría nace de saberse unido a Cristo: «Para mí la vida es Cristo y la muerte, una ganancia» (1,21)."),
    ("El dirigente joven", "Una dirigente de 17 años siente que los adultos de la parroquia no la toman en serio.", ["¿Qué le dice 1 Timoteo 4,12?", "¿Qué le pide a ella el mismo texto?"]),
    [["Cartas de la cautividad", "Filipenses, Colosenses, Efesios y Filemón."], ["Cartas pastorales", "1 y 2 Timoteo y Tito."], ["Kénosis", "Despojo de Cristo (Filipenses 2,7)."]],
    ["Alégrense siempre en el Señor. ¿Qué te quita la alegría?", "Reza el himno de Filipenses 2.", "Visita o llama a alguien que esté pasando por un duelo."],
    ["Elijan una carta.", "Léanla completa.", "Elijan una frase.", "Compartan."],
    "Tener los sentimientos de Cristo es el corazón de la vida cristiana."),
 ],
 [P("¿Dónde nació Pablo?", ["Jerusalén", "Tarso de Cilicia", "Damasco"], 1, "Era judío de la diáspora con ciudadanía romana."),
  P("¿Cómo describe Pablo su experiencia de Damasco en Gálatas?", ["Como un cambio de religión", "Como una revelación del Hijo y un llamado a anunciarlo", "Como un sueño"], 1, "Gálatas 1,15-16."),
  P("¿Cuál es probablemente el escrito más antiguo del Nuevo Testamento?", ["Romanos", "1 Tesalonicenses", "Hebreos"], 1, "Hacia el año 50."),
  P("¿Cuántas cartas se consideran escritas personalmente por Pablo?", ["Siete", "Trece", "Catorce"], 0, "Romanos, 1 y 2 Corintios, Gálatas, Filipenses, 1 Tesalonicenses y Filemón."),
  P("¿Qué significa ser justificado por la fe?", ["Ganarse a Dios con obras", "Ser hecho justo por gracia, mediante la fe en Cristo", "No tener que hacer el bien"], 1, "La fe actúa por el amor."),
  P("¿Qué texto de Pablo es el relato más antiguo de la institución de la Eucaristía?", ["1 Corintios 11,23-26", "Romanos 8", "Filipenses 2"], 0, "Anterior a los evangelios."),
  P("¿Qué es lo más grande según 1 Corintios 13?", ["La fe", "La esperanza", "El amor"], 2, "El amor permanece."),
  P("¿Qué virtud se repite en Filipenses?", ["La alegría", "La obediencia", "El ayuno"], 0, "Escrita desde la cárcel."),
 ])

MODULOS = [SE4, SE5, SE6]
